const body = $input.first().json.body || $input.first().json;
function clean(value) { return String(value || '').trim(); }
function sql(value) { return clean(value).replace(/'/g, "''"); }
const mascotas = Array.isArray(body.mascotas) ? body.mascotas.map((m) => ({
  nombre: clean(m.nombre),
  especie: clean(m.especie),
  raza: clean(m.raza),
  observaciones: clean(m.observaciones)
})).filter((m) => m.nombre && m.especie) : [];
const cliente = {
  identificacion: clean(body.identificacion),
  nombres: clean(body.nombres),
  apellidos: clean(body.apellidos),
  telefono: clean(body.telefono),
  email: clean(body.email).toLowerCase(),
  direccion: clean(body.direccion),
  mascotas
};
const faltantes = ['identificacion', 'nombres', 'apellidos', 'telefono', 'email'].filter((campo) => !cliente[campo]);
if (!mascotas.length) faltantes.push('mascotas');
if (faltantes.length) {
  throw new Error(`Faltan campos obligatorios: ${faltantes.join(', ')}`);
}
return [{ json: {
  ...cliente,
  sql_identificacion: sql(cliente.identificacion),
  sql_nombres: sql(cliente.nombres),
  sql_apellidos: sql(cliente.apellidos),
  sql_telefono: sql(cliente.telefono),
  sql_email: sql(cliente.email),
  sql_direccion: sql(cliente.direccion),
  sql_mascotas_json: sql(JSON.stringify(mascotas))
} }];

const body = $input.first().json.body || $input.first().json;
function clean(value) { return String(value || '').trim(); }
function sql(value) { return clean(value).replace(/'/g, "''"); }
const tipo = clean(body.tipo_caso || body.tipo || 'Consulta general');
const hora = clean(body.hora).slice(0, 5);
const idVeterinario = Number(body.id_veterinario || body.veterinario || 0);
const prioridades = { 'Emergencia': 'Alta', 'Consulta general': 'Media', 'Vacunacion': 'Baja' };
const cita = {
  identificacion: clean(body.identificacion),
  mascota: clean(body.mascota),
  especie: clean(body.especie),
  id_veterinario: idVeterinario,
  tipo_caso: tipo,
  prioridad: prioridades[tipo] || 'Media',
  fecha: clean(body.fecha),
  hora,
  hora_formateada: body.hora_formateada || hora,
  observaciones: clean(body.observaciones || body.obs)
};
const faltantes = ['identificacion', 'mascota', 'especie', 'tipo_caso', 'fecha', 'hora'].filter((campo) => !cita[campo]);
if (!idVeterinario) faltantes.push('id_veterinario');
if (faltantes.length) {
  throw new Error(`Faltan campos obligatorios: ${faltantes.join(', ')}`);
}
return [{ json: {
  ...cita,
  sql_identificacion: sql(cita.identificacion),
  sql_mascota: sql(cita.mascota),
  sql_especie: sql(cita.especie),
  sql_tipo_caso: sql(cita.tipo_caso),
  sql_fecha: sql(cita.fecha),
  sql_hora: sql(cita.hora),
  sql_observaciones: sql(cita.observaciones)
} }];

const input = $input.first().json;
const query = input.query || {};
function clean(value) { return String(value || '').trim(); }
function sql(value) { return clean(value).replace(/'/g, "''"); }
const identificacion = clean(query.identificacion || input.identificacion);
if (!identificacion) throw new Error('Debe enviar identificacion.');
return [{ json: { identificacion, sql_identificacion: sql(identificacion) } }];

const clientes = new Map();
for (const item of $input.all()) {
  const row = item.json;
  const id = row.id_cliente;
  if (!clientes.has(id)) {
    clientes.set(id, {
      id,
      identificacion: row.identificacion,
      nombres: row.nombres,
      apellidos: row.apellidos,
      telefono: row.telefono,
      email: row.email,
      direccion: row.direccion,
      mascotas: []
    });
  }
  if (row.id_mascota) {
    clientes.get(id).mascotas.push({
      id: row.id_mascota,
      nombre: row.mascota_nombre,
      especie: row.mascota_especie,
      raza: row.mascota_raza,
      observaciones: row.mascota_observaciones
    });
  }
}
return [{ json: { success: true, clientes: [...clientes.values()] } }];

const body = $input.first().json.body || $input.first().json;
function clean(value) { return String(value || '').trim(); }
function sql(value) { return clean(value).replace(/'/g, "''"); }
const id = Number(body.id_veterinario || body.id || 0);
const veterinario = {
  id_veterinario: Number.isInteger(id) && id > 0 ? id : null,
  nombres: clean(body.nombres),
  apellidos: clean(body.apellidos),
  especialidad: clean(body.especialidad),
  telefono: clean(body.telefono)
};
const faltantes = ['nombres', 'apellidos'].filter((campo) => !veterinario[campo]);
if (faltantes.length) {
  throw new Error(`Faltan campos obligatorios: ${faltantes.join(', ')}`);
}
return [{ json: {
  ...veterinario,
  sql_id: veterinario.id_veterinario || 'NULL',
  sql_nombres: sql(veterinario.nombres),
  sql_apellidos: sql(veterinario.apellidos),
  sql_especialidad: sql(veterinario.especialidad),
  sql_telefono: sql(veterinario.telefono)
} }];

const body = $input.first().json.body || $input.first().json;
const id = Number(body.id_veterinario || body.id || 0);
const activo = Number(body.activo);
if (!Number.isInteger(id) || id <= 0) throw new Error('Debe enviar id_veterinario valido.');
if (![0, 1].includes(activo)) throw new Error('Debe enviar activo 0 o 1.');
return [{ json: { id_veterinario: id, activo } }];

