const input = $input.first().json;
const query = input.query || {};
function clean(value) { return String(value || '').trim(); }
function sql(value) { return clean(value).replace(/'/g, "''"); }
const fecha = clean(query.fecha || input.fecha);
const idVeterinario = Number(query.id_veterinario || input.id_veterinario || 0);
if (!fecha) throw new Error('Debe enviar fecha.');
if (!Number.isInteger(idVeterinario) || idVeterinario <= 0) throw new Error('Debe enviar id_veterinario valido.');
return [{ json: { fecha, id_veterinario: idVeterinario, sql_fecha: sql(fecha) } }];

const horarios = $input.all().map((item) => ({
  hora: item.json.hora,
  disponible: item.json.disponible === 1 || item.json.disponible === true || item.json.disponible === '1',
  estado: item.json.estado || null
}));
return [{ json: { success: true, horarios } }];

const input = $input.first().json;
const body = input.body || input;
const id = Number(body.id_cita || body.id || 0);
if (!Number.isInteger(id) || id <= 0) {
  throw new Error('Debe enviar un id_cita valido.');
}
return [{ json: { id_cita: id } }];

